window.ToyData.register("exercises-biology.json","[{\"type\":\"self\",\"prompt\":\"判断下列说法是否正确。正确的画“√”，错误的画“×”。(2) 植物可以吸收氧气，释放出二氧化碳气体。\",\"answer\":\"√（植物也进行呼吸，能吸入氧气并呼出二氧化碳）\",\"explanation\":\"教材指出“绝大多数生物需要吸入氧气，呼出二氧化碳”，植物属于生物，也应具有呼吸这一共同特征。\",\"id\":\"cnb_k7acpt5_q121002\",\"topicId\":\"cnb_k7acpt5\",\"linkedTopicIds\":[\"cnb_k7acpt5\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7a_rjb_exe2\",\"sourceBook\":\"七年级上册\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"判断下列说法是否正确。正确的画“√”，错误的画“×”。(4) 生物都是由细胞构成的。\",\"answer\":\"×\",\"explanation\":\"教材明确“除病毒以外，生物都是由细胞构成的”，因此“生物都是由细胞构成”不严谨。\",\"id\":\"cnb_k7acpt11_q121004\",\"topicId\":\"cnb_k7acpt11\",\"linkedTopicIds\":[\"cnb_k7acpt11\",\"cnb_k7acpt12\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7a_rjb_exe4\",\"sourceBook\":\"七年级上册\",\"difficulty\":\"standard\"},{\"type\":\"self\",\"prompt\":\"由形态相似、结构和功能相同的细胞联合在一起形成的细胞群叫做什么？\",\"answer\":\"组织。\",\"id\":\"cnb_k7acpt68_q121011\",\"topicId\":\"cnb_k7acpt68\",\"linkedTopicIds\":[\"cnb_k7acpt68\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7a_rjb_exe11\",\"sourceBook\":\"七年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"简述人体结构层次从微观到宏观的组成顺序。\",\"answer\":\"细胞→组织→器官→系统→人体（个体）。\",\"id\":\"cnb_k7acpt72_q121012\",\"topicId\":\"cnb_k7acpt72\",\"linkedTopicIds\":[\"cnb_k7acpt72\",\"cnb_k7askl12\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7a_rjb_exe12\",\"sourceBook\":\"七年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：藻类植物具有根、茎、叶的分化。（  ）\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错误。藻类植物没有根、茎、叶的分化。\",\"explanation\":\"依据教材“藻类植物没有根、茎、叶的分化”。\",\"id\":\"cnb_k7acpt81_q121014\",\"topicId\":\"cnb_k7acpt81\",\"linkedTopicIds\":[\"cnb_k7acpt81\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7a_rjb_exe14\",\"sourceBook\":\"七年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断：叶绿素是绿叶进行光合作用的主要场所。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"×（主要场所是叶绿体，叶绿素起捕获光的作用）\",\"explanation\":\"教材指出“利用光提供的能量，在叶绿体中合成淀粉等有机物”，并说明叶绿素用于捕获太阳光。\",\"id\":\"cnb_k7acpt52_q121022\",\"topicId\":\"cnb_k7acpt52\",\"linkedTopicIds\":[\"cnb_k7acpt52\",\"cnb_k7acpt133\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7a_rjb_exe22\",\"sourceBook\":\"七年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：一个地区内生长的所有植物叫做这个地区的植被。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"正确。\",\"explanation\":\"直接考查“植被”的教材定义。\",\"id\":\"cnb_k7acpt150_q121025\",\"topicId\":\"cnb_k7acpt150\",\"linkedTopicIds\":[\"cnb_k7acpt150\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7a_rjb_exe25\",\"sourceBook\":\"七年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"馒头在口腔中细嚼会逐渐变甜。请解释馒头变甜的原因，并写出涉及的主要物质变化。\",\"answer\":\"馒头主要成分是淀粉。牙齿咀嚼和舌搅拌使馒头与唾液充分混合，唾液中的唾液淀粉酶将部分淀粉分解为有甜味的麦芽糖，因此会感觉变甜。主要变化：淀粉→麦芽糖。\",\"explanation\":\"从“甜味出现”追溯到“淀粉本无甜味、分解产物麦芽糖有甜味”，再指出条件为“充分混合+唾液淀粉酶”。\",\"id\":\"cnb_k7bcpt49_q122002\",\"topicId\":\"cnb_k7bcpt49\",\"linkedTopicIds\":[\"cnb_k7bcpt49\",\"cnb_k7bcpt48\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7b_rjb_exe2\",\"sourceBook\":\"七年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"简述吸气与呼气时胸腔容积、肺内气体压力以及气体进出的变化关系。\",\"answer\":\"吸气时肋间肌和膈肌收缩使胸腔容积扩大，肺扩张，肺内气体压力降低，外界气体被吸入；呼气时肋间肌和膈肌舒张使胸腔容积缩小，肺收缩，肺内气体压力升高，气体被呼出。\",\"id\":\"cnb_k7bcpt73_q122005\",\"topicId\":\"cnb_k7bcpt73\",\"linkedTopicIds\":[\"cnb_k7bcpt73\",\"cnb_k7bcpt74\",\"cnb_k7bcpt76\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7b_rjb_exe5\",\"sourceBook\":\"七年级下册\",\"difficulty\":\"standard\"},{\"type\":\"choice\",\"prompt\":\"判断题：人体排尿的作用只是排出废物，与维持内环境稳定无关。（  ）\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错误。排尿不仅排出废物，而且能调节体内水和无机盐平衡，维持组织细胞正常生理功能。\",\"explanation\":\"教材原文指出排尿“对调节体内水和无机盐的平衡，维持组织细胞的正常生理功能，也有重要的作用”。\",\"id\":\"cnb_k7bcpt128_q122010\",\"topicId\":\"cnb_k7bcpt128\",\"linkedTopicIds\":[\"cnb_k7bcpt128\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7b_rjb_exe10\",\"sourceBook\":\"七年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"请按顺序写出听觉形成的大致过程（从声波进入耳开始到产生听觉为止）。\",\"answer\":\"声波经外耳道传到鼓膜→鼓膜振动经听小骨传到内耳→刺激耳蜗内对声波敏感的感觉细胞→感觉细胞将声音信息通过听觉神经传到大脑一定区域→产生听觉。\",\"id\":\"cnb_k7bcpt140_q122012\",\"topicId\":\"cnb_k7bcpt140\",\"linkedTopicIds\":[\"cnb_k7bcpt140\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7b_rjb_exe12\",\"sourceBook\":\"七年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"什么是反射？反射弧由哪些基本结构组成？\",\"answer\":\"反射：人体通过神经系统，对外界或内部各种刺激所发生的有规律的反应。反射弧的基本结构：感受器、传入神经、神经中枢、传出神经、效应器。\",\"id\":\"cnb_k7bcpt147_q122013\",\"topicId\":\"cnb_k7bcpt147\",\"linkedTopicIds\":[\"cnb_k7bcpt147\",\"cnb_k7bcpt148\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7b_rjb_exe13\",\"sourceBook\":\"七年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"常温下，某雨水样品用pH试纸测得pH=5.2。该雨水是否属于酸雨？说明判断依据。\",\"answer\":\"属于酸雨。依据：正常雨水pH不小于5.6，pH小于5.6的雨水为酸雨；该样品pH=5.2<5.6。\",\"explanation\":\"识记并应用酸雨判定阈值pH<5.6。\",\"id\":\"cnb_k7bcpt163_q122014\",\"topicId\":\"cnb_k7bcpt163\",\"linkedTopicIds\":[\"cnb_k7bcpt163\",\"cnb_k7bcpt164\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_7b_rjb_exe14\",\"sourceBook\":\"七年级下册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：水螅的身体只能分出上下，分不出前后、左右和背腹，因此水螅的身体属于辐射对称。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"正确。\",\"explanation\":\"辐射对称的判定要点是：只能分上下，不能分前后左右背腹，且绕纵轴可有多个对称切面。\",\"id\":\"cnb_k8acpt2_q124001\",\"topicId\":\"cnb_k8acpt2\",\"linkedTopicIds\":[\"cnb_k8acpt2\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8a_rjb_exe1\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断：先天性行为和学习行为是两种截然不同、互不相关的行为类型。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错误。\",\"explanation\":\"教材指出“先天性行为是学习行为的基础”，二者相关而非互不相关。\",\"id\":\"cnb_k8acpt57_q124003\",\"topicId\":\"cnb_k8acpt57\",\"linkedTopicIds\":[\"cnb_k8acpt57\",\"cnb_k8acpt58\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8a_rjb_exe3\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"刚出生的婴儿就会吃奶，这属于哪一类行为？这对他（她）的生存有什么意义？\",\"answer\":\"属于先天性行为；有利于获得营养，维持生存并促进生长发育。\",\"explanation\":\"“先天性行为”由遗传物质决定、生来就有；吃奶可保证新生儿获取能量与物质。\",\"id\":\"cnb_k8acpt57_q124004\",\"topicId\":\"cnb_k8acpt57\",\"linkedTopicIds\":[\"cnb_k8acpt57\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8a_rjb_exe4\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"动物的分类除了比较形态结构外，还往往要比较什么？\",\"answer\":\"还往往要比较动物的生理功能。\",\"id\":\"cnb_k8acpt120_q124013\",\"topicId\":\"cnb_k8acpt120\",\"linkedTopicIds\":[\"cnb_k8acpt120\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8a_rjb_exe13\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"教材指出生物多样性的内涵包括哪三个方面？\",\"answer\":\"包括生物种类的多样性、基因的多样性和生态系统的多样性。\",\"id\":\"cnb_k8acpt123_q124014\",\"topicId\":\"cnb_k8acpt123\",\"linkedTopicIds\":[\"cnb_k8acpt123\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8a_rjb_exe14\",\"sourceBook\":\"八年级上册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"美丽的蝴蝶是由“毛毛虫”变成的，那么“毛毛虫”与“蝴蝶”分别处于发育的哪个阶段？（）\",\"answer\":\"D\",\"choices\":[{\"key\":\"A\",\"text\":\"幼虫、卵\"},{\"key\":\"B\",\"text\":\"蛹、若虫\"},{\"key\":\"C\",\"text\":\"若虫、成虫\"},{\"key\":\"D\",\"text\":\"幼虫、成虫。\"}],\"sourceAnswer\":\"D（幼虫、成虫）\",\"explanation\":\"完全变态昆虫的发育阶段为卵—幼虫—蛹—成虫；“毛毛虫”对应幼虫阶段，“蝴蝶”对应成虫阶段。\",\"id\":\"cnb_k8bcpt7_q125001\",\"topicId\":\"cnb_k8bcpt7\",\"linkedTopicIds\":[\"cnb_k8bcpt7\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8b_rjb_exe1\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：相对性状指“同种生物同一性状的不同表现形式”，例如番茄果实的红色与黄色属于一对相对性状。（对/错）\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"对。\",\"explanation\":\"相对性状强调“同种生物”“同一性状”“不同表现形式”，番茄果实颜色的红/黄符合定义。\",\"id\":\"cnb_k8bcpt19_q125002\",\"topicId\":\"cnb_k8bcpt19\",\"linkedTopicIds\":[\"cnb_k8bcpt19\",\"cnb_k8bskl4\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8b_rjb_exe2\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"传染病在人群中流行必须同时具备哪三个基本环节？缺少其中任何一个环节会怎样？\",\"answer\":\"三个基本环节是：传染源、传播途径、易感人群。缺少其中任何一个环节，传染病就流行不起来。\",\"explanation\":\"直接依据教材对“传染病流行三个基本环节”的定义作答。\",\"id\":\"cnb_k8bcpt48_q125007\",\"topicId\":\"cnb_k8bcpt48\",\"linkedTopicIds\":[\"cnb_k8bcpt48\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_8b_rjb_exe7\",\"sourceBook\":\"八年级下册\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断正误：二糖一般要水解成单糖才能被细胞吸收。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"正确。\",\"explanation\":\"教材指出“二糖……一般要水解成单糖才能被细胞吸收”。\",\"id\":\"cnb_kbx1cpt42_q131009\",\"topicId\":\"cnb_kbx1cpt42\",\"linkedTopicIds\":[\"cnb_kbx1cpt42\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx1_rjb_exe9\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"（判断题）构成细胞膜的磷脂分子具有流动性，而蛋白质是固定不动的。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错误。蛋白质大多也能运动，膜具有流动性。\",\"explanation\":\"流动镶嵌模型指出磷脂可侧向移动，膜中蛋白质大多也能运动。\",\"id\":\"cnb_kbx1cpt92_q131015\",\"topicId\":\"cnb_kbx1cpt92\",\"linkedTopicIds\":[\"cnb_kbx1cpt92\",\"cnb_kbx1cpt93\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx1_rjb_exe15\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"细胞核内行使遗传功能的结构是 (   )\",\"answer\":\"C\",\"choices\":[{\"key\":\"A\",\"text\":\"核膜\"},{\"key\":\"B\",\"text\":\"核孔\"},{\"key\":\"C\",\"text\":\"染色质\"},{\"key\":\"D\",\"text\":\"核仁\"}],\"sourceAnswer\":\"C\",\"explanation\":\"染色质主要由DNA和蛋白质组成，其中DNA是遗传信息的载体，因此细胞核内行使遗传功能的结构是染色质。\",\"id\":\"cnb_kbx1cpt113_q131019\",\"topicId\":\"cnb_kbx1cpt113\",\"linkedTopicIds\":[\"cnb_kbx1cpt113\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx1_rjb_exe19\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"酵母菌在有氧条件下细胞呼吸的主要产物是（ ）。\",\"answer\":\"C\",\"choices\":[{\"key\":\"A\",\"text\":\"酒精和二氧化碳\"},{\"key\":\"B\",\"text\":\"乳酸\"},{\"key\":\"C\",\"text\":\"二氧化碳和水\"},{\"key\":\"D\",\"text\":\"水和酒精\"}],\"sourceAnswer\":\"C\",\"explanation\":\"教材指出：有氧条件下酵母菌产生大量二氧化碳和水；无氧条件下产生酒精并产生少量二氧化碳。\",\"id\":\"cnb_kbx1cpt175_q131030\",\"topicId\":\"cnb_kbx1cpt175\",\"linkedTopicIds\":[\"cnb_kbx1cpt175\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx1_rjb_exe30\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"在探究酵母菌细胞呼吸方式的对比实验中，若用澄清石灰水检测CO2，则观察到石灰水变浑浊说明（ ）。\",\"answer\":\"说明有CO2产生。\",\"explanation\":\"教材明确：CO2可使澄清石灰水变浑浊。\",\"id\":\"cnb_kbx1cpt174_q131031\",\"topicId\":\"cnb_kbx1cpt174\",\"linkedTopicIds\":[\"cnb_kbx1cpt174\",\"cnb_kbx1skl30\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx1_rjb_exe31\",\"sourceBook\":\"必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：减数分裂II前通常没有间期，且染色体不再复制。（  ）\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"对。\",\"explanation\":\"原文指出“减数分裂I与减数分裂II之间通常没有间期，或者间期时间很短，染色体不再复制”。\",\"id\":\"cnb_kbx2cpt34_q132006\",\"topicId\":\"cnb_kbx2cpt34\",\"linkedTopicIds\":[\"cnb_kbx2cpt34\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx2_rjb_exe6\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"判断题：判断一种设想或假说是否正确，只要能够解释已有的实验现象就足够了。（  ）\",\"answer\":\"错误。还应运用假说—演绎法预测新实验结果，并通过实验检验。\",\"explanation\":\"教材指出“仅能解释已有的实验现象是不够的，还应运用假说—演绎法，预测……再通过实验来检验”。\",\"id\":\"cnb_kbx2skl2_q132009\",\"topicId\":\"cnb_kbx2skl2\",\"linkedTopicIds\":[\"cnb_kbx2skl2\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx2_rjb_exe9\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"一位女性红绿色盲患者（基因型XbXb）与一位色觉正常的男性（基因型XBY）结婚，预测其子女的表型。\",\"answer\":\"女儿均为XBXb（正常携带者）；儿子均为XbY（色盲）。\",\"explanation\":\"父亲的X^B只传给女儿，母亲的X^b传给所有子女；儿子从父亲获得Y而从母亲获得X^b，因此全为色盲。\",\"id\":\"cnb_kbx2cpt58_q132011\",\"topicId\":\"cnb_kbx2cpt58\",\"linkedTopicIds\":[\"cnb_kbx2cpt58\",\"cnb_kbx2skl10\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx2_rjb_exe11\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断正误：基因数目一定等于生物体内DNA分子数目。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错误。一个DNA分子上分布着许多个基因，例如大肠杆菌1个DNA分子上分布约4.4×10^3个基因。\",\"explanation\":\"教材指出“一个DNA分子上有许多个基因”。因此DNA分子数与基因数一般不相同。\",\"id\":\"cnb_k8acpt127_q132019\",\"topicId\":\"cnb_k8acpt127\",\"linkedTopicIds\":[\"cnb_k8acpt127\",\"cnb_kbx2cpt70\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx2_rjb_exe19\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断正误：只有生殖细胞中的染色体数目或结构的变化才属于染色体变异。（ ）\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错误\",\"explanation\":\"教材定义：体细胞或生殖细胞内染色体数目或结构的变化都称为染色体变异。\",\"id\":\"cnb_kbx2cpt136_q132027\",\"topicId\":\"cnb_kbx2cpt136\",\"linkedTopicIds\":[\"cnb_kbx2cpt136\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_bx2_rjb_exe27\",\"sourceBook\":\"必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"判断题：缩手反射和膝跳反射都属于条件反射。（  ）并说明理由。\",\"answer\":\"错误。缩手反射和膝跳反射都是与生俱来的反射，属于非条件反射。\",\"explanation\":\"依据教材“缩手反射和膝跳反射都是与生俱来的……出生后无须训练就具有的反射叫作非条件反射”。\",\"id\":\"cnb_kxzxbx1cpt49_q141008\",\"topicId\":\"cnb_kxzxbx1cpt49\",\"linkedTopicIds\":[\"cnb_kxzxbx1cpt49\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx1_rjb_exe8\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"被免疫细胞识别的外来分子是 (   )\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"抗体\"},{\"key\":\"B\",\"text\":\"抗原\"},{\"key\":\"C\",\"text\":\"细胞因子\"},{\"key\":\"D\",\"text\":\"溶菌酶\"}],\"sourceAnswer\":\"B\",\"explanation\":\"抗原是“能引发免疫反应的物质”，可与免疫细胞表面受体结合并被识别；抗体、细胞因子、溶菌酶属于免疫活性物质。\",\"id\":\"cnb_k8bcpt57_q141021\",\"topicId\":\"cnb_k8bcpt57\",\"linkedTopicIds\":[\"cnb_k8bcpt57\",\"cnb_kxzxbx1skl23\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx1_rjb_exe21\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：与HIV感染者握手、拥抱等一般接触会使人感染HIV。（对/错）\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错。教材指出与HIV感染者的一般接触，如握手、拥抱等，不会使人感染HIV。\",\"explanation\":\"考查对艾滋病传播途径与非传播情境的区分。\",\"id\":\"cnb_kxzxbx1cpt193_q141027\",\"topicId\":\"cnb_kxzxbx1cpt193\",\"linkedTopicIds\":[\"cnb_kxzxbx1cpt193\",\"cnb_kxzxbx1skl29\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx1_rjb_exe27\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"在调节种子萌发的过程中，若某激素促进萌发、另一激素抑制萌发，则这两种激素之间属于哪种作用关系？请举出教材中的一对激素作为例子。\",\"answer\":\"属于拮抗作用。例子：赤霉素促进种子萌发，脱落酸抑制种子萌发。\",\"explanation\":\"同一过程作用效果相反即为拮抗；教材明确给出赤霉素与脱落酸在种子萌发中的相反作用。\",\"id\":\"cnb_kxzxbx1cpt224_q141032\",\"topicId\":\"cnb_kxzxbx1cpt224\",\"linkedTopicIds\":[\"cnb_kxzxbx1cpt224\",\"cnb_kxzxbx1cpt218\",\"cnb_kxzxbx1cpt220\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx1_rjb_exe32\",\"sourceBook\":\"选择性必修一\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"死亡率是指在单位时间内死亡的个体数目占该种群个体总数的比值。（判断对错）\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"正确。\",\"explanation\":\"该表述与教材对死亡率的定义一致。\",\"id\":\"cnb_kxzxbx2cpt4_q142002\",\"topicId\":\"cnb_kxzxbx2cpt4\",\"linkedTopicIds\":[\"cnb_kxzxbx2cpt4\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx2_rjb_exe2\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"两种生物共同生活时双方都受益，但分开后各自也能独立生活。这种种间关系称为（  ）\",\"answer\":\"原始合作（互惠）\",\"explanation\":\"依据教材对“原始合作（互惠）”的定义：共同生活受益但不相互依存。\",\"id\":\"cnb_kxzxbx2cpt45_q142008\",\"topicId\":\"cnb_kxzxbx2cpt45\",\"linkedTopicIds\":[\"cnb_kxzxbx2cpt45\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx2_rjb_exe8\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"一个物种在群落中的地位或作用，包括所处空间位置、占用资源情况以及与其他物种关系等，称为该物种的什么？\",\"answer\":\"生态位\",\"explanation\":\"直接对应教材对“生态位（niche）”的概念表述。\",\"id\":\"cnb_kxzxbx2cpt52_q142009\",\"topicId\":\"cnb_kxzxbx2cpt52\",\"linkedTopicIds\":[\"cnb_kxzxbx2cpt52\",\"cnb_kxzxbx2skl17\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx2_rjb_exe9\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"某草地群落在水平方向上，不同地段往往分布着不同的种群，同一地段种群密度也有差别，这种分布格局常呈（  ）分布。\",\"answer\":\"镶嵌分布\",\"explanation\":\"对应“水平结构……常呈镶嵌分布”。\",\"id\":\"cnb_kxzxbx2cpt50_q142010\",\"topicId\":\"cnb_kxzxbx2cpt50\",\"linkedTopicIds\":[\"cnb_kxzxbx2cpt50\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx2_rjb_exe10\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断：初生演替与次生演替是根据演替的起始条件划分的；初生演替通常速度较慢、阶段较多，次生演替通常速度较快、阶段较少。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"正确。\",\"explanation\":\"题干直接对应教材对两类演替的划分依据与差异描述。\",\"id\":\"cnb_kxzxbx2cpt71_q142013\",\"topicId\":\"cnb_kxzxbx2cpt71\",\"linkedTopicIds\":[\"cnb_kxzxbx2cpt71\",\"cnb_kxzxbx2cpt72\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx2_rjb_exe13\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：食物链彼此相互交错连接成的复杂营养关系叫作食物网。\",\"answer\":\"A\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"正确。\",\"explanation\":\"食物网的定义是多条食物链相互交错连接形成的复杂营养关系。\",\"id\":\"cnb_k7acpt29_q142015\",\"topicId\":\"cnb_k7acpt29\",\"linkedTopicIds\":[\"cnb_k7acpt29\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx2_rjb_exe15\",\"sourceBook\":\"选择性必修二\",\"difficulty\":\"basic\"},{\"type\":\"choice\",\"prompt\":\"判断题：消毒与灭菌的区别在于，消毒可杀死物体内外所有微生物（包括芽孢和孢子），而灭菌只杀死一部分微生物。\",\"answer\":\"B\",\"choices\":[{\"key\":\"A\",\"text\":\"正确\"},{\"key\":\"B\",\"text\":\"错误\"}],\"sourceAnswer\":\"错误。消毒是杀死一部分微生物；灭菌是杀死所有微生物，包括芽孢和孢子。\",\"explanation\":\"依据教材对“消毒/灭菌”的定义进行对比。\",\"id\":\"cnb_kxzxbx3cpt20_q143003\",\"topicId\":\"cnb_kxzxbx3cpt20\",\"linkedTopicIds\":[\"cnb_kxzxbx3cpt20\",\"cnb_kxzxbx3cpt21\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx3_rjb_exe3\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"多数动物细胞在体外培养时适宜的pH范围是多少？CO2在动物细胞培养中的主要作用是什么？（填空）\",\"answer\":\"适宜pH：7.2～7.4；CO2主要作用：维持培养液的pH。\",\"id\":\"cnb_kxzxbx3cpt60_q143010\",\"topicId\":\"cnb_kxzxbx3cpt60\",\"linkedTopicIds\":[\"cnb_kxzxbx3cpt60\",\"cnb_kxzxbx3cpt61\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx3_rjb_exe10\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"（基于“DNA的粗提取与鉴定”）将预冷95%酒精加入到处理后的洋葱提取液中，观察到白色丝状物析出。写出这一现象出现的主要原因，并指出该白色丝状物主要是什么物质。\",\"answer\":\"原因：DNA不溶于酒精，加入酒精后DNA从溶液中析出并聚集成丝状。白色丝状物主要为粗提取的DNA（可能夹带少量杂质）。\",\"explanation\":\"用“溶解性差异”解释酒精沉淀，并将观察到的丝状物对应到DNA。\",\"id\":\"cnb_kxzxbx3cpt105_q143014\",\"topicId\":\"cnb_kxzxbx3cpt105\",\"linkedTopicIds\":[\"cnb_kxzxbx3cpt105\",\"cnb_kxzxbx3skl17\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx3_rjb_exe14\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"},{\"type\":\"self\",\"prompt\":\"PCR扩增目的基因时，每次循环通常包括哪三个基本步骤？并说明引物在PCR中的作用是什么。\",\"answer\":\"三个步骤是变性、复性（退火）、延伸。引物是一段与模板链互补的短单链核酸，能与模板特定位点结合，为DNA聚合酶提供3'端起始点，使DNA聚合酶从引物3'端开始连接脱氧核苷酸并延伸合成新链，从而实现对特定片段的特异性扩增。\",\"explanation\":\"题目直接对应教材对PCR循环步骤与引物作用的定义性表述。\",\"id\":\"cnb_kxzxbx3cpt112_q143015\",\"topicId\":\"cnb_kxzxbx3cpt112\",\"linkedTopicIds\":[\"cnb_kxzxbx3cpt112\",\"cnb_kxzxbx3cpt113\",\"cnb_kxzxbx3skl20\"],\"source\":\"k12-exercise\",\"sourceId\":\"biology_xzxbx3_rjb_exe15\",\"sourceBook\":\"选择性必修三\",\"difficulty\":\"basic\"}]");
